// src/components/User/CheckoutPage.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './CheckoutPage.css';

// --- ADD THIS HOOK BACK ---
function useSwipe({ onSwipe, sensitivity = 50 }) {
  const [touchStart, setTouchStart] = useState(null);
  const [touchEnd, setTouchEnd] = useState(null);

  const onTouchStart = (e) => setTouchStart(e.targetTouches[0].clientX);
  const onTouchMove = (e) => setTouchEnd(e.targetTouches[0].clientX);

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isRightSwipe = distance < -sensitivity; // Swiping right
    
    if (isRightSwipe) {
      onSwipe();
    }
    setTouchStart(null);
    setTouchEnd(null);
  };

  return { onTouchStart, onTouchMove, onTouchEnd };
}

// --- UPDATE THE PROPS ---
export default function CheckoutPage({ cart = [], updateCart, placeOrder, tables = [], userDetails }) {
  const navigate = useNavigate();
  const [orderType, setOrderType] = useState('Dine In');
  const [instructions, setInstructions] = useState('');
  const [showInstructionsModal, setShowInstructionsModal] = useState(false);
  
  // --- UPDATE THE FORM STATE TO USE userDetails ---
  const [name, setName] = useState(userDetails?.name || '');
  const [phone, setPhone] = useState(userDetails?.phone || '');
  const [address, setAddress] = useState(userDetails?.address || '');
  const [members, setMembers] = useState(userDetails?.persons || '2');
  
  const availableTables = tables.filter(t => t.status === 'Available');

  const subtotal = cart.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const deliveryCharge = orderType === 'Takeaway' ? 50 : 0;
  const taxes = subtotal * 0.05;
  const grandTotal = subtotal + deliveryCharge + taxes;

  const handlePlaceOrder = () => {
    if (!name || !phone) {
      alert('Please fill in your Name and Contact number.');
      return;
    }
    if (orderType === 'Takeaway' && !address) {
      alert('Please fill in your delivery address.');
      return;
    }
    
    placeOrder({
      type: orderType,
      name,
      phone,
      address: orderType === 'Takeaway' ? address : null,
      members: orderType === 'Dine In' ? members : null,
      tableNum: orderType === 'Dine In' ? availableTables[0]?.number : null,
      instructions,
    });
    navigate('/thankyou');
  };

  // --- ADD THIS LINE BACK ---
  const swipeHandlers = useSwipe({ onSwipe: handlePlaceOrder });

  return (
    <div className="mobile-container checkout-page">
      <header className="checkout-header">
        <button className="back-btn" onClick={() => navigate(-1)}>←</button>
        <h2>Your Order</h2>
      </header>
      
      <div className="order-type-toggle">
        <button 
          className={orderType === 'Dine In' ? 'active' : ''}
          onClick={() => setOrderType('Dine In')}
        >
          Dine In
        </button>
        <button 
          className={orderType === 'Takeaway' ? 'active' : ''}
          onClick={() => setOrderType('Takeaway')}
        >
          Take Away
        </button>
      </div>

      <div className="cart-summary">
        {cart.map(item => (
          <div key={item.id} className="cart-item-checkout">
            <img src={item.image} alt={item.name} className="cart-item-image" />
            <div className="cart-item-info">
              <h3>{item.name}</h3>
              <p>₹{item.price}</p>
            </div>

            {/* --- UPDATE THIS TO A RED 'X' BUTTON --- */}
            <button className="remove-item-btn" onClick={() => updateCart(item.id, 0)}>
              ×
            </button>
          </div>
        ))}
      </div>

      <button className="instructions-btn" onClick={() => setShowInstructionsModal(true)}>
        Add cooking instructions (optional) 
      </button>

      {/* Bill Details */}
      <div className="bill-details">
        {/* ... bill rows are correct ... */}
        <div className="bill-row">
          <span>Item Total</span>
          <span>₹{subtotal.toFixed(2)}</span>
        </div>
        {orderType === 'Takeaway' && (
          <div className="bill-row">
            <span>Delivery Charge</span>
            <span>₹{deliveryCharge.toFixed(2)}</span>
          </div>
        )}
        <div className="bill-row">
          <span>Taxes</span>
          <span>₹{taxes.toFixed(2)}</span>
        </div>
        <div className="bill-row grand-total">
          <span>Grand Total</span>
          <span>₹{grandTotal.toFixed(2)}</span>
        </div>
      </div>

      {/* User Details Form */}
      <div className="user-details-form">
        <h3>Your Details</h3> {/* CHANGED TITLE */}
        <div className="form-group-user">
          <label>Name</label>
          <input type="text" placeholder="full name" value={name} onChange={(e) => setName(e.target.value)} />
        </div>
        <div className="form-group-user">
          <label>Contact</label>
          <input type="tel" placeholder="phone" value={phone} onChange={(e) => setPhone(e.target.value)} />
        </div>
        
        {orderType === 'Dine In' && (
          <div className="form-group-user">
            <label>Number of Members</label>
            <input type="number" placeholder="2, 4, 6" value={members} onChange={(e) => setMembers(e.target.value)} />
          </div>
        )}
        
        {orderType === 'Takeaway' && (
          <div className="form-group-user">
            <label>Address</label>
            <input type="text" placeholder="Complete address" value={address} onChange={(e) => setAddress(e.target.value)} />
            <p className="delivery-time">Delivery in 42 mins</p>
          </div>
        )}
      </div>
      
      {/* --- REVERT THIS TO THE SWIPE BUTTON --- */}
      <div className="swipe-to-order" {...swipeHandlers}>
        <div className="swipe-arrow">→</div>
        <span>Swipe to Order</span>
      </div>

      {/* ... modal stays the same ... */}
      {showInstructionsModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <h3>Add Cooking instructions</h3>
            <p>The restaurant will try its best to follow your request. However, refunds or cancellations in this regard won't be possible</p>
            <textarea 
              value={instructions}
              onChange={(e) => setInstructions(e.target.value)}
              rows="4"
              placeholder="Enter instructions..."
            />
            <div className="modal-actions">
              <button className="modal-btn-cancel" onClick={() => setShowInstructionsModal(false)}>Cancel</button>
              <button className="modal-btn-next" onClick={() => setShowInstructionsModal(false)}>Next</button>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}
